#define main llmx_cli_main
#include "C:/Users/Marko/Desktop/Projects/llmx/src/cli/main.cpp"
#undef main
int main() {
    auto weights=build_synthetic_model(2,256,1024,8,2,32,512,12345u);
    infer::Model model(weights);
    for(int nt: {1,6}) {
        model.set_threads(nt);
        for(int count: {1,2,4,8,16,64}) {
            std::vector<uint32_t> ids(count);
            for(int i=0;i<count;++i) ids[i]=i;
            std::vector<float> logits;
            for(int i=0;i<10;++i) {model.reset(); logits=model.prefill(ids);}
            auto start=std::chrono::steady_clock::now();
            for(int i=0;i<100;++i) {model.reset(); logits=model.prefill(ids);}
            double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count()/100;
            double sum=0;for(float x:logits) {if(!std::isfinite(x)) return 2;sum+=x;}
            std::cout << std::setprecision(12) << "{\"threads\":"<<nt<<",\"batch\":"<<count<<",\"ms\":"<<ms<<",\"sum\":"<<sum<<"}\n";
        }
    }
}

