#include <algorithm>
#include <chrono>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <stdexcept>
#include <vector>
#include <map>
#include <tuple>
#ifdef LLMX_COMPARE_REFERENCE
#include "llama.h"
#else
#include "model/arch_qwen.hpp"
#endif
using Clock = std::chrono::steady_clock;
struct ProfileCpu : backend::CpuBackend {
    std::map<std::tuple<size_t,size_t,size_t>,double> matrices;
    double attention_ms=0, elementwise_ms=0;
    bool in_attention=false;
    void matmul(uint32_t type,const uint8_t* data,const float* X,float* Y,size_t ni,size_t no,size_t nb) override {
        auto start=Clock::now();
        CpuBackend::matmul(type,data,X,Y,ni,no,nb);
        matrices[{ni,no,nb}]+=std::chrono::duration<double,std::milli>(Clock::now()-start).count();
    }
    void attention(const float* Q,const float* K,const float* V,float* out,int h,int hk,int d,int past,int batch) override {
        auto start=Clock::now();in_attention=true;
        CpuBackend::attention(Q,K,V,out,h,hk,d,past,batch);
        in_attention=false;attention_ms+=std::chrono::duration<double,std::milli>(Clock::now()-start).count();
    }
    void parallel_for(int n,const std::function<void(int)>& fn) override {
        auto start=Clock::now();CpuBackend::parallel_for(n,fn);
        if(!in_attention) elementwise_ms+=std::chrono::duration<double,std::milli>(Clock::now()-start).count();
    }
    void reset_profile() {matrices.clear();attention_ms=elementwise_ms=0;}
    void report(const char* phase) {
        std::cerr<<phase<<" attention_ms="<<attention_ms<<" parallel_elementwise_ms="<<elementwise_ms<<"\n";
        for(const auto& item:matrices) std::cerr<<phase<<" matmul "<<std::get<0>(item.first)<<" "<<std::get<1>(item.first)<<" "<<std::get<2>(item.first)<<" ms="<<item.second<<"\n";
    }
};
int main(int argc, char ** argv) {
    if (argc != 3) {
        std::cerr << "usage: compare-cpu MODEL.gguf TOKEN_IDS.txt\n";
        return 2;
    }
    std::ifstream input(argv[2]);
    std::vector<uint32_t> ids;
    uint32_t id;
    while (input >> id) ids.push_back(id);
    if (ids.size() != 247) throw std::runtime_error("expected 247 pinned HF tokens");
    const size_t np = ids.size() - 32;
    std::vector<uint32_t> prompt(ids.begin(), ids.begin() + np);
#ifdef LLMX_COMPARE_REFERENCE
    llama_backend_init();
    auto mp = llama_model_default_params();
    mp.n_gpu_layers = 0;
    mp.load_mode = LLAMA_LOAD_MODE_NONE;
    auto * model = llama_model_load_from_file(argv[1], mp);
    if (!model) return 3;
    auto cp = llama_context_default_params();
    cp.n_ctx = 512;
    cp.n_batch = (uint32_t)np;
    cp.n_ubatch = 128;
    cp.n_threads = cp.n_threads_batch = 6;
    cp.type_k = cp.type_v = GGML_TYPE_F32;
    cp.flash_attn_type = LLAMA_FLASH_ATTN_TYPE_DISABLED;
    cp.offload_kqv = cp.op_offload = false;
    auto * ctx = llama_init_from_model(model, cp);
    if (!ctx) return 4;
    const size_t nv = llama_vocab_n_tokens(llama_model_get_vocab(model));
    std::vector<llama_token> ref_ids(ids.begin(), ids.end());
#else
    auto weights = gguf::read_gguf(argv[1]);
    auto profiler=std::make_shared<ProfileCpu>();
    infer::Model model(weights,profiler);
    model.set_threads(6);
    model.set_ubatch(128);
#endif
    for (int run = 0; run < 2; ++run) {
#ifdef LLMX_COMPARE_REFERENCE
        llama_memory_clear(llama_get_memory(ctx), true);
#else
        model.reset();
#endif
        profiler->reset_profile();
        const auto start = Clock::now();
#ifdef LLMX_COMPARE_REFERENCE
        if (llama_decode(ctx, llama_batch_get_one(ref_ids.data(), (int32_t)np))) return 5;
        llama_synchronize(ctx);
#else
        auto logits = model.prefill(prompt);
#endif
        const auto pp_end = Clock::now();
        profiler->report("prefill");profiler->reset_profile();
        for (size_t i = np; i < ids.size(); ++i) {
#ifdef LLMX_COMPARE_REFERENCE
            if (llama_decode(ctx, llama_batch_get_one(&ref_ids[i], 1))) return 6;
            llama_synchronize(ctx);
#else
            logits = model.step(ids[i]);
#endif
        }
        const auto tg_end = Clock::now();
        profiler->report("decode");
#ifdef LLMX_COMPARE_REFERENCE
        const float * values = llama_get_logits_ith(ctx, -1);
#else
        const float * values = logits.data();
        const size_t nv = logits.size();
#endif
        double sum = 0;
        for (size_t i = 0; i < nv; ++i) {
            if (!std::isfinite(values[i])) return 7;
            sum += values[i];
        }
        std::cout << std::setprecision(10) << "{\"run\":" << run
                  << ",\"pp_tokens\":" << np << ",\"tg_tokens\":32,\"pp_ms\":"
                  << std::chrono::duration<double,std::milli>(pp_end-start).count()
                  << ",\"tg_ms\":" << std::chrono::duration<double,std::milli>(tg_end-pp_end).count()
                  << ",\"top1\":" << (std::max_element(values,values+nv)-values)
                  << ",\"logit_sum\":" << sum << "}" << std::endl;
    }
#ifdef LLMX_COMPARE_REFERENCE
    llama_free(ctx);
    llama_model_free(model);
    llama_backend_free();
#endif
}
